# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TENVİN VE SAKİN NUNUN (نْ) HÂLLERİNE GİRİŞ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SAKİN NUN (نْ) VE TENVİN (ـً ـٍ ـٌ) NEDİR?</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Sakin Nun (نْ):</text>\n  <text x="50" y="114" font-size="10.5" fill="#1e40af">Harekesi olmayan, üzerinde cezim (sükûn) bulunan</text>\n  <text x="50" y="128" font-size="10.5" fill="#1e40af">nun harfidir (مَنْ، عَنْ، مِنْ، أَنْعَمْتَ، يَنْهَوْنَ).</text>\n  <text x="42" y="154" font-size="11.5" font-weight="bold" fill="#1e3a8a">• Tenvin (ـً / ـٍ / ـٌ):</text>\n  <text x="50" y="172" font-size="10.5" fill="#1e40af">Kelimenin sonunda yazılışta iki üstün, iki esre veya</text>\n  <text x="50" y="186" font-size="10.5" fill="#1e40af">iki ötre olarak görünen; okunuşta kelimenin sonuna</text>\n  <text x="50" y="200" font-size="10.5" fill="#1e40af">cezimli bir nun (-en, -in, -un) sesi katan işarettir.</text>\n  <text x="182" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">Her ikisi de ses olarak cezimli "n" (نْ) ile biter!</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TENVİN VE SAKİN NUNUN 4 TEMEL HÜKMÜ</text>\n  <text x="377" y="96" font-size="11" font-weight="bold" fill="#14532d">1. İZHAR (الإظْهَارُ): Açık ve net okuma (6 boğaz harfi)</text>\n  <text x="377" y="122" font-size="11" font-weight="bold" fill="#14532d">2. İHFA (الإخْفَاءُ): Gunneli gizleyerek okuma (15 harf)</text>\n  <text x="377" y="148" font-size="11" font-weight="bold" fill="#14532d">3. İDGAM (الإدْغَامُ): Sonraki harfe katma (6 يَرْمَلُونَ harfi)</text>\n  <text x="385" y="166" font-size="10.5" fill="#166534">• İdgam-ı Meal-Gunne (ي، ن، م، و) ve Bilâ-Gunne (ل، ر)</text>\n  <text x="377" y="192" font-size="11" font-weight="bold" fill="#14532d">4. İKLAB (الإقْلَابُ): Mim (م) harfine çevirme (1 harf: ب)</text>\n  <text x="517" y="222" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Toplam 28 Arapça harf: 6 + 15 + 6 + 1 = 28</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">1. İZHAR (الإظْهَارُ الْحَلْقِيُّ) KURALI VE 6 BOĞAZ HARFİ</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">İZHAR HARFLERİ (حُرُوفُ الْحَلْقِ — 6 HARF)</text>\n  <rect x="45" y="82" width="275" height="42" rx="8" fill="#fef08a"/>\n  <text x="182" y="110" text-anchor="middle" font-size="18" font-weight="bold" fill="#713f12">ء (أ) — هـ — ع — ح — غ — خ</text>\n  <text x="45" y="146" font-size="11" font-weight="bold" fill="#713f12">• Tanım: Tenvin veya sakin nundan sonra bu 6 boğaz</text>\n  <text x="53" y="162" font-size="11" font-weight="bold" fill="#713f12">harfinden biri gelirse nun sesi AÇIKÇA okunur.</text>\n  <text x="45" y="186" font-size="11" fill="#713f12">• Nasıl Okunur? Gunne (geniz sesi), tutma veya</text>\n  <text x="53" y="202" font-size="11" fill="#713f12">uzatma yapmadan, dil ucu damağa değerek net okunur.</text>\n  <text x="182" y="226" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#854d0e">Ezber Beyti İlk Kelimeleri: أَخِي هَاكَ عِلْمًا حَازَهُ غَيْرُ خَاسِرٍ</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">KUR\'AN-I KERİM\'DEN İZHAR ÖRNEKLERİ</text>\n  <text x="380" y="96" font-size="12" font-weight="bold" fill="#7c2d12">• ء (Hemze): مَنْ آمَنَ  /  كُلٌّ آمَنَ  /  عَذَابٌ أَلِيمٌ</text>\n  <text x="380" y="122" font-size="12" font-weight="bold" fill="#7c2d12">• هـ (Hê): مِنْ هَادٍ  /  يَنْهَوْنَ  /  سَلَامٌ هِيَ</text>\n  <text x="380" y="148" font-size="12" font-weight="bold" fill="#7c2d12">• ع (Ayın): أَنْعَمْتَ  /  مِنْ عِلْمٍ  /  سَمِيعٌ عَلِيمٌ</text>\n  <text x="380" y="174" font-size="12" font-weight="bold" fill="#7c2d12">• ح (Hâ): وَانْحَرْ  /  مِنْ حَكِيمٍ  /  عَلِيمٌ حَكِيمٌ</text>\n  <text x="380" y="200" font-size="12" font-weight="bold" fill="#7c2d12">• غ (Gayın): مِنْ غِلٍّ  /  قَوْلًا غَيْرَ  ·  خ (Hı): مِنْ خَوْفٍ</text>\n  <text x="517" y="226" text-anchor="middle" font-size="10.5" fill="#9a3412">Aynı kelimede de iki ayrı kelimede de olabilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">2. İHFA (الإخْفَاءُ) KURALI, 15 HARFİ VE UYGULANIŞI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">İHFA HARFLERİ (15 HARF)</text>\n  <rect x="40" y="78" width="285" height="48" rx="8" fill="#f3e8ff"/>\n  <text x="182" y="98" text-anchor="middle" font-size="14" font-weight="bold" fill="#581c87">ت، ث، ج، د، ذ، ز، س، ش</text>\n  <text x="182" y="118" text-anchor="middle" font-size="14" font-weight="bold" fill="#581c87">ص، ض، ط، ظ، ف، ق، ك</text>\n  <text x="42" y="146" font-size="11" font-weight="bold" fill="#581c87">• Tanım: Tenvin veya sakin nundan sonra bu 15</text>\n  <text x="50" y="162" font-size="11" font-weight="bold" fill="#581c87">harften biri geldiğinde nun sesini GİZLEYEREK okumak.</text>\n  <text x="42" y="186" font-size="10.5" fill="#4c1d95">• Uygulama: Dil ucu damağa değdirilmez; ses genizden</text>\n  <text x="50" y="202" font-size="10.5" fill="#4c1d95">(gunne ile) 1-1,5 elif miktarı tutulup sonraki harfe geçilir.</text>\n  <text x="182" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6b21a8">İzhar ile İdgam arasında şeddesiz gunneli okunuştur.</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">KUR\'AN-I KERİM\'DEN İHFA ÖRNEKLERİ</text>\n  <text x="380" y="96" font-size="12" font-weight="bold" fill="#1e3a8a">• أَنْتُمْ (entum - ت)  ·  مَنْثُورًا (mensûrâ - ث)</text>\n  <text x="380" y="122" font-size="12" font-weight="bold" fill="#1e3a8a">• مَنْ جَاءَ (men câe - ج)  ·  أَنْدَادًا (endâdâ - د)</text>\n  <text x="380" y="148" font-size="12" font-weight="bold" fill="#1e3a8a">• الْإِنْسَانُ (el-insânu - س)  ·  مِنْ شَرِّ (min şerri - ش)</text>\n  <text x="380" y="174" font-size="12" font-weight="bold" fill="#1e3a8a">• يَنْصُرْكُمْ (yensurkum - ص)  ·  مِنْ طَيِّبَاتِ (ط)</text>\n  <text x="380" y="200" font-size="12" font-weight="bold" fill="#1e3a8a">• مِنْ قَبْلِ (min kabli - ق)  ·  مَنْ كَانَ / كِتَابٌ كَرِيمٌ (ك)</text>\n  <text x="517" y="226" text-anchor="middle" font-size="10.5" fill="#1d4ed8">Kalın harften (ص، ض، ط، ظ، ق) önce gunne kalınlaşır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
